function fragileLinks(hubs, links) {
  const clusters = (skip) => {
    const parent = Array.from({ length: hubs }, (_, i) => i);
    const find = (x) => { while (parent[x] !== x) x = parent[x] = parent[parent[x]]; return x; };
    let count = hubs;
    links.forEach(([a, b], id) => {
      if (id === skip) return;
      const ra = find(a), rb = find(b);
      if (ra !== rb) { parent[ra] = rb; count--; }
    });
    return count;
  };
  const base = clusters(-1);
  return links
    .filter((_, id) => clusters(id) > base)
    .map(([a, b]) => (a < b ? [a, b] : [b, a]))
    .sort((x, y) => x[0] - y[0] || x[1] - y[1]);
}

