function fragileLinks(hubs, links) {
  const adj = Array.from({ length: hubs }, () => []);
  links.forEach(([a, b], id) => { adj[a].push([b, id]); adj[b].push([a, id]); });
  const order = new Array(hubs).fill(-1), low = new Array(hubs).fill(0);
  const bridges = [];
  let clock = 0;
  const dfs = (u, via) => {
    order[u] = low[u] = clock++;
    for (const [v, id] of adj[u]) {
      if (id === via) continue;
      if (order[v] === -1) {
        dfs(v, id);
        low[u] = Math.min(low[u], low[v]);
        if (low[v] > order[u]) bridges.push(u < v ? [u, v] : [v, u]);
      } else low[u] = Math.min(low[u], order[v]);
    }
  };
  for (let h = 0; h < hubs; h++) if (order[h] === -1) dfs(h, -1);
  return bridges.sort((x, y) => x[0] - y[0] || x[1] - y[1]);
}
